interface.signature:
class PostgresSink:
    def __init__(self, session_factory: Callable[[], Session]): ...
    def handle_event(self, event: EpistemicEvent) -> None: ...

class PostgresAuditQueryService:
    def get_forensic_timeline(
        self, 
        knowledge_unit_id: UUID,
        start_time: datetime = None,
        end_time: datetime = None,
    ) -> list[EpistemicEvent]: ...

sql-examples.query:
SELECT * FROM epistemic_events 
WHERE knowledge_unit_id = 'xxx' AND event_type = 'promotion'
ORDER BY timestamp;

SELECT * FROM epistemic_events 
WHERE event_type = 'usage_violation'
AND timestamp > NOW() - INTERVAL '24 hours';
